from docx import Document

def load(p):
    d = Document(p)
    heads = [x.text.strip() for x in d.paragraphs if x.style.name.startswith('Heading')]
    words = sum(len(x.text.split()) for x in d.paragraphs)
    words += sum(len(c.text.split()) for t in d.tables for r in t.rows for c in r.cells)
    return d, heads, words

d0, h0, w0 = load("docs/superpowers/specs/2026-09-19-central-rdc-pool-allocation-brd-fsd.docx")
d1, h1, w1 = load("docs/superpowers/specs/2026-09-21-central-rdc-pool-allocation-brd-fsd-v1.1.docx")

print(f"{'':22} {'v1.0':>8} {'v1.1':>8}")
for lbl, a, b in (("sections", len(h0), len(h1)),
                  ("tables", len(d0.tables), len(d1.tables)),
                  ("words", w0, w1),
                  ("list items", len([x for x in d0.paragraphs if x.style.name.startswith('List')]),
                                len([x for x in d1.paragraphs if x.style.name.startswith('List')]))):
    print(f"{lbl:22} {a:>8} {b:>8}   {b-a:+}")

print("\nSECTIONS ADDED IN v1.1:")
for x in h1:
    if x not in h0: print("  +", x)
print("\nSECTIONS REMOVED:")
for x in h0:
    if x not in h1: print("  -", x)

def rows(d, needle):
    out = []
    for t in d.tables:
        for r in t.rows:
            c0 = r.cells[0].text.strip()
            if c0.startswith(needle): out.append(c0)
    return out

for tag in ("BR-RDC-", "I-", "V", "O"):
    a, b = set(rows(d0, tag)), set(rows(d1, tag))
    if b - a: print(f"\nNEW {tag} ROWS:", sorted(b - a))
